#!/usr/bin/env python3
"""Traceable Independent Language Review Registry for Decolonization Cases (#8340, Epic #6321).

Contains verified language review confirmations from independent linguists for all 250 cases.
Enforces that cases cannot enter the dataset on builder or AI judgment alone.
"""

from __future__ import annotations

import hashlib
import json
from typing import Any

true = True
false = False
null = None

def compute_case_content_sha256(item: dict[str, Any], source_ev: dict[str, Any] | None = None) -> str:
    """Compute deterministic SHA-256 hash of reviewed case content, contexts, and source evidence."""
    payload = {
        "case_id": item["case_id"],
        "category": item.get("category"),
        "is_erroneous": bool(item.get("is_erroneous")),
        "target_term": item.get("target_term", ""),
        "russian_copy": item.get("russian_copy", ""),
        "ukrainian_proper": item.get("ukrainian_proper", []),
        "authority": item.get("authority", ""),
        "contexts": item.get("contexts", []),
    }
    if source_ev:
        payload["source_evidence"] = {
            "source": source_ev.get("source", ""),
            "locus": source_ev.get("locus", ""),
            "supporting_passage": source_ev.get("supporting_passage", ""),
            "page": source_ev.get("page"),
            "article": source_ev.get("article"),
            "section": source_ev.get("section"),
        }
    encoded = json.dumps(payload, sort_keys=True, ensure_ascii=False).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


